$search = trim(is_string($_GET['q'] ?? null) ? $_GET['q'] : '');
$subjectFilter = (int)($_GET['subject'] ?? 0);
$gradeFilter = is_string($_GET['grade'] ?? null) ? $_GET['grade'] : '';
$filtered = array_values(array_filter($records, function($r) use ($search, $subjectFilter, $gradeFilter) {
    $haystack = $r['student_name'].' '.$r['matric_number'].' '.$r['subject_name'].' '.$r['subject_code'].' '.$r['academic_term'];
    $tokens = preg_split('/\s+/u', mb_strtolower($search), -1, PREG_SPLIT_NO_EMPTY);
    foreach ($tokens as $token) if (!str_contains(mb_strtolower($haystack), $token)) return false;
    return (!$subjectFilter || (int)$r['subject_id'] === $subjectFilter) && (!$gradeFilter || ($gradeFilter === 'pending' ? $r['final_grade'] === null : $r['final_grade'] === $gradeFilter));
}));
?>
