<div class="performance-layout"><section class="panel distribution"><div class="panel-heading"><div><h2>Grade distribution</h2><p>Number of completed results by final grade</p></div></div><?php if (!$finished): ?><p class="chart-empty">All results are awaiting marks. Complete an assessment to see the distribution.</p><?php else: ?><div class="chart" aria-label="Grade distribution for <?= e($term ?: 'all terms') ?>"><?php foreach($distribution as $g=>$count): ?><div class="chart-row"><span class="grade <?= strtolower($g) ?>"><?= $g ?></span><meter min="0" max="<?= count($finished) ?>" value="<?= $count ?>" aria-label="Grade <?= $g ?>, <?= $count ?> results"><?= $count ?></meter><strong><?= $count ?></strong></div><?php endforeach ?></div><p class="chart-caption">Source: saved results · <?= e($term ?: 'all terms') ?> · <?= count($finished) ?> completed results. Bar length represents result count.</p><?php endif ?></section>
<section class="panel subject-summary"><div class="panel-heading"><div><h2>By subject</h2><p>Average mark (%) across completed results</p></div></div><div class="subject-summary-list"><?php foreach ($subjects as $s): $all = array_values(array_filter($termRecords,fn($r)=>(int)$r['subject_id']===(int)$s['id'])); if (!$all) continue; $done=array_values(array_filter($all,fn($r)=>$r['total_marks']!==null)); $avg=$done?array_sum(array_column($done,'total_marks'))/count($done):null; ?><div class="subject-summary-row"><div><strong><?= e($s['name']) ?></strong><small><?= e($s['code']) ?> · <?= count($done) ?>/<?= count($all) ?> complete</small></div><strong><?= $avg===null?'—':number_format($avg,1).'%' ?></strong></div><?php endforeach ?></div><p class="chart-caption">Source: saved results · <?= e($term ?: 'all terms') ?>. Each result has equal weight.</p></section></div>
<section class="panel"><div class="panel-heading"><div><h2>A little extra support</h2><p>Completed results below 40%, so you can plan the next conversation.</p></div></div><?php $support=array_filter($finished,fn($r)=>(float)$r['total_marks']<40); if (!$support): ?><div class="support-clear"><?= icon('check') ?><p>No completed results below 40% in this selection.</p></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>STUDENT</th><th>SUBJECT / TERM</th><th class="number">TOTAL</th><th>GRADE</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody><?php foreach($support as $r): ?><tr><td><strong><?= e($r['student_name']) ?></strong><small><?= e($r['matric_number']) ?></small></td><td><?= e($r['subject_name']) ?><small><?= e($r['academic_term']) ?></small></td><td class="number"><?= marks($r['total_marks']) ?></td><td><span class="grade e">E</span></td><td><a class="row-link" href="<?= e(url('result',['id'=>$r['id']])) ?>">View <?= icon('arrow') ?></a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><?php endif ?>
